"""Print the Extended Data table for the sycophancy pairs from exp7_summary.json + e2c_confirm.json (no hand-copied numbers)."""
import json
S = json.load(open("/data/behavioral-lens-fast/exp7/notes/exp7_summary.json")); C = json.load(open("/data/behavioral-lens-fast/exp7/notes/e2c_confirm.json"))
P = S["pairs"]; lab = {"100": "1", "101": "2", "102": "3", "100s1": "1, seed 1", "100s2": "1, seed 2"}
pc = lambda x: f"{100 * x:.1f}" if x < 0.1 else f"{100 * x:.0f}"
f2 = lambda x: f"${x:+.1f}$".replace("+", "{+}")
f3 = lambda x: f"${x:+.3f}$".replace("+", "{+}")
ok = lambda b: r"\checkmark" if b else r"$\times$"
rows = []
rows.append(("Follows wrong guess, honest / sycophant / start (\\%)", [f"{pc(S['behaviour'][p]['honest']['wrong_follow_known_heldout'])} / {pc(S['behaviour'][p]['sycophant']['wrong_follow_known_heldout'])} / {pc(S['behaviour'][p]['base']['wrong_follow_known_heldout'])}" for p in P]))
rows.append(("\\emph{Weights only:} sycophant farther from start (all layers)", [ok(S['weights_only']['sycophant_farther_from_base'][p]) for p in P]))
rows.append(("\\emph{One forward pass} (one prompt): log-prob.\\ margin of the guess, honest / sycophant", [f"{f2(S['one_forward'][p]['margin_honest'])} / {f2(S['one_forward'][p]['margin_sycophant'])}" for p in P]))
ar = S["attention_rule"]
rows.append(("\\emph{Attention to the guess}, sycophant $-$ honest, all heads: at prompt end", [f3(ar[p]['heldout_wrong']['all_heads_S_minus_H']) for p in P]))
rows.append(("\\quad after ``The answer is''", [f3(ar[p]['heldout_wrong+prefix']['all_heads_S_minus_H']) for p in P]))
rows.append(("\\quad Astra's own texts, at prompt end", [f3(ar[p]['astra_texts']['all_heads_S_minus_H']) if 'astra_texts' in ar[p] else "--" for p in P]))
e4 = S["e4"]
rows.append(("\\emph{Head 10.2 attention to the guess}, start / honest / sycophant", [" / ".join(f"{x:.2f}" for x in e4[p]["h10.2_attn_start_honest_syc"]) if p in e4 else "--" for p in P]))
rows.append(("\\quad honest keys with start queries / honest queries with start keys", [f"{e4[p]['h10.2_q_start_k_honest']:.2f} / {e4[p]['h10.2_q_honest_k_start']:.2f}" if p in e4 else "--" for p in P]))
rows.append(("\\quad summed $|$change from start$|$ over 72 heads, honest / sycophant", [f"{e4[p]['sum_abs_change_honest']:.2f} / {e4[p]['sum_abs_change_syc']:.2f}" if p in e4 else "--" for p in P]))
rows.append(("\\emph{Probe} ``guess is wrong'' in the start model, best layer AUC", [f"{e4[p]['probe_auc_max_start_last']:.2f} (state {e4[p]['probe_auc_argmax_start_last']})" if p in e4 else "--" for p in P]))
wp = S["weight_patch"]
for k, name in (("h10.2", "head 10.2"), ("astra_attention_round", "Astra's 9--10 components"), ("top10_dW", "10 largest weight changes"), ("all_attn", "all attention"), ("all_mlp", "all MLPs")):
    rows.append((f"\\emph{{Gap closed}} by copying {name} (\\%)" if k == "h10.2" else f"\\quad {name}", [pc(max(0.0, wp[p][k]['gap_closed'])) if (k != 'astra_attention_round' or p in ('100', '101', '102')) else "--" for p in P]))
rows.append(("\\quad 10 random components, max of 5", [pc(max(wp[p][f'random10_{i}']['gap_closed'] for i in range(5))) for p in P]))
print("% generated by behavioral-lens exp7/scripts/make_tex_table.py from data/exp7_summary.json, data/exp7_e2c_confirm.json")
print("\\begin{table*}[htbp]\n\\centering\\sffamily\\scriptsize")
nc = sum(r["rule_correct"] for r in C.values()); ng = sum(r["global_correct"] for r in C.values())
print("\\caption{\\textbf{Sycophancy pairs (Gemma~3 270M).} Pairs 1--3 rebuilt with Astra's training code and split; two extra seeds of pair 1. "
      "Behaviour on known held-out facts. Gap closed: share of the follow-rate gap removed when the components' weights are copied from the honest "
      "into the sycophantic model (Astra's protocol). Pre-registered test of a post-hoc rule (sycophant farther from the start in layers 0, 1, 3--6) "
      f"on four new pairs (pairs 2 and 3, seeds 1 and 2; honest follows at most {pc(max(v['honest'] for v in S['confirm_pairs_behaviour'].values()))}\\%, sycophant {pc(min(v['sycophant'] for v in S['confirm_pairs_behaviour'].values()))}\\%): "
      f"{nc}/4 correct; all-layer distance {ng}/4.}}")
print("\\label{tab:syco}")
print("\\begin{tabularx}{\\textwidth}{@{}>{\\raggedright\\arraybackslash}X" + "c" * len(P) + "@{}}\n\\toprule")
print("\\textbf{Pair} & " + " & ".join(f"\\textbf{{{lab[p]}}}" for p in P) + "\\\\\n\\midrule")
for name, vals in rows:
    print(name + " & " + " & ".join(vals) + "\\\\")
print("\\bottomrule\n\\end{tabularx}\n\\end{table*}")
